import '../setup-filesystem-isolation.js';
import {performance} from 'node:perf_hooks';
import {withTempWorkspaceEnv} from '../helpers.js';
import {FileCredentialStore} from '../../src/agent-pool/credential-store.js';
import {createAgentPoolServices} from '../../src/agent-pool/service-factory.js';
import {ModelRegistry,ModelRuntime,SettingsManager} from '@earendil-works/pi-coding-agent';
const reads={count:0};const original=FileCredentialStore.prototype.read;FileCredentialStore.prototype.read=async function(...args:Parameters<typeof original>){reads.count++;return Reflect.apply(original,this,args);};
try{await withTempWorkspaceEnv('factory-profile-',{},async ws=>{for(const refreshOnCreate of [true,false])for(let repeat=0;repeat<3;repeat++){const count=reads.count,cpu=process.cpuUsage(),start=performance.now(),credentialStore=new FileCredentialStore(`${ws.base}/auth.json`),modelRuntime=await ModelRuntime.create({credentials:credentialStore,modelsPath:null,allowModelNetwork:false,refreshOnCreate});const bootstrapMs=performance.now()-start,at=performance.now();createAgentPoolServices({getDurableSession:()=>undefined,pool:new Map(),authStorage:credentialStore,modelRuntime,modelRegistry:new ModelRegistry(modelRuntime),settingsManager:SettingsManager.inMemory(),workspaceDir:ws.workspace});console.log(JSON.stringify({refreshOnCreate,repeat,bootstrapMs,factoryMs:performance.now()-at,credentialReads:reads.count-count,cpuUs:process.cpuUsage(cpu),scope:'isolated empty credential file/public SDK runtime; no model/provider/network requests'}));}});}finally{FileCredentialStore.prototype.read=original;}
